import React from "react";
import { apiFetch } from "./api";
import { formatGhc } from "./money";
import { h } from "./h";

/**
 * @param {string | null | undefined} accessToken
 * @param {{ type: string, productId?: string, meta?: Record<string, unknown> }} payload
 */
export function trackVendorAnalyticsEvent(accessToken, payload) {
  if (!accessToken || !payload?.type) return;
  void apiFetch("/api/vendor/analytics/events", {
    method: "POST",
    headers: { Authorization: `Bearer ${accessToken}` },
    json: payload
  }).catch(() => {});
}

/** @param {{ daily: Array<{ date: string; revenue: number; orderCount: number; eventCounts?: Record<string, number> }> }} props */
export function VendorRevenueLineChart({ daily }) {
  const w = 520;
  const svgH = 160;
  const padX = 28;
  const padY = 22;
  const vals = (daily || []).map((d) => Number(d.revenue) || 0);
  const max = Math.max(...vals, 1);
  const n = Math.max((daily || []).length, 1);
  const innerW = w - padX * 2;
  const innerH = svgH - padY * 2;
  const step = n > 1 ? innerW / (n - 1) : 0;
  const pts = (daily || []).map((d, i) => {
    const x = padX + i * step;
    const y = padY + innerH * (1 - (Number(d.revenue) || 0) / max);
    return `${x},${y}`;
  });
  const points = pts.join(" ");
  const gridY = [0, 0.5, 1].map((t) => {
    const y = padY + innerH * (1 - t);
    return h("line", {
      key: `g-${t}`,
      x1: padX,
      x2: w - padX,
      y1: y,
      y2: y,
      stroke: "rgba(148,163,184,0.2)",
      strokeWidth: 1
    });
  });
  const tickStep = Math.max(1, Math.ceil(n / 5));
  const xLabels = (daily || []).map((d, i) =>
    i % tickStep === 0 || i === n - 1
      ? h(
          "text",
          {
            key: `xl-${d.date}`,
            x: padX + i * step,
            y: svgH - 4,
            fontSize: 9,
            fill: "rgb(148 163 184)",
            textAnchor: "middle"
          },
          d.date.slice(5)
        )
      : null
  );
  return h("div", { className: "w-full" }, [
    h(
      "svg",
      {
        key: "svg",
        viewBox: `0 0 ${w} ${svgH}`,
        className: "h-36 w-full max-w-full",
        role: "img",
        "aria-label": "Revenue by day",
        preserveAspectRatio: "xMidYMid meet"
      },
      [
        ...gridY,
        h("polyline", {
          key: "line",
          fill: "none",
          stroke: "rgb(56 189 248)",
          strokeWidth: 2,
          strokeLinejoin: "round",
          strokeLinecap: "round",
          points
        }),
        ...(daily || []).map((d, i) => {
          const x = padX + i * step;
          const y = padY + innerH * (1 - (Number(d.revenue) || 0) / max);
          return h("circle", {
            key: `c-${d.date}`,
            cx: x,
            cy: y,
            r: 2.5,
            fill: "rgb(125 211 252)",
            stroke: "rgb(15 23 42)",
            strokeWidth: 0.75
          });
        }),
        ...xLabels.filter(Boolean)
      ]
    ),
    h("p", { key: "cap", className: "mt-1.5 text-center text-[11px] text-slate-500 dark:text-slate-400" }, "Seller proceeds by day (UTC)")
  ]);
}

const PIE_COLORS = [
  "rgb(56 189 248)",
  "rgb(129 140 248)",
  "rgb(52 211 153)",
  "rgb(251 191 36)",
  "rgb(244 114 182)",
  "rgb(148 163 184)",
  "rgb(94 234 212)"
];

function pieSlicePath(cx, cy, r, a0, a1) {
  const x0 = cx + r * Math.cos(a0);
  const y0 = cy + r * Math.sin(a0);
  const x1 = cx + r * Math.cos(a1);
  const y1 = cy + r * Math.sin(a1);
  const large = a1 - a0 > Math.PI ? 1 : 0;
  return `M ${cx} ${cy} L ${x0} ${y0} A ${r} ${r} 0 ${large} 1 ${x1} ${y1} Z`;
}

/** @param {{ topProducts: Array<{ productId: string; name: string; revenue: number }> }} props */
export function VendorTopProductsPieChart({ topProducts }) {
  const rows = (topProducts || []).filter((p) => Number(p.revenue) > 0);
  const maxSlices = 6;
  let slices = [];
  if (rows.length === 0) {
    return h("p", { className: "py-8 text-center text-sm text-slate-500 dark:text-slate-400" }, "No sales data yet.");
  }
  const sorted = [...rows].sort((a, b) => Number(b.revenue) - Number(a.revenue));
  const head = sorted.slice(0, maxSlices);
  const tail = sorted.slice(maxSlices);
  const otherRev = tail.reduce((s, p) => s + Number(p.revenue), 0);
  slices = head.map((p) => ({ name: p.name, revenue: Number(p.revenue) }));
  if (otherRev > 0) slices.push({ name: "Other", revenue: otherRev });

  const total = slices.reduce((s, x) => s + x.revenue, 0) || 1;
  let angle = -Math.PI / 2;
  const cx = 100;
  const cy = 100;
  const r = 78;

  const paths = slices.map((s, i) => {
    const sweep = (s.revenue / total) * 2 * Math.PI;
    const a0 = angle;
    const a1 = angle + sweep;
    angle = a1;
    const path = pieSlicePath(cx, cy, r, a0, a1);
    return h("path", {
      key: `${s.name}-${i}`,
      d: path,
      fill: PIE_COLORS[i % PIE_COLORS.length],
      stroke: "rgba(15,23,42,0.35)",
      strokeWidth: 0.5,
      title: `${s.name}: ${formatGhc(s.revenue)}`
    });
  });

  const legend = slices.map((s, i) =>
    h("div", { key: `lg-${i}`, className: "flex min-w-0 items-center gap-2 text-[11px] text-slate-600 dark:text-slate-300" }, [
      h("span", {
        key: "sw",
        className: "h-2 w-2 shrink-0 rounded-full",
        style: { backgroundColor: PIE_COLORS[i % PIE_COLORS.length] }
      }),
      h("span", { className: "min-w-0 flex-1 truncate", title: s.name }, s.name),
      h("span", { className: "shrink-0 font-medium text-slate-800 dark:text-slate-100" }, formatGhc(s.revenue))
    ])
  );

  return h("div", { className: "flex flex-col items-center gap-3 sm:flex-row sm:items-start sm:justify-center sm:gap-6" }, [
    h(
      "svg",
      {
        key: "pie",
        viewBox: "0 0 200 200",
        className: "h-36 w-36 shrink-0",
        role: "img",
        "aria-label": "Revenue share by product"
      },
      paths
    ),
    h("div", { key: "leg", className: "w-full max-w-[14rem] space-y-1.5" }, legend)
  ]);
}
